script.text:
			&OutlineEntry;

function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete);
	if (f._convection) f._convection = null;
	var a = ['ma_hd'];
	if (f._extensions === undefined) f._extensions = [];
	if (f._extensions.length > 0) setReferenceValue(f, a);
	else {
		changeLookupReadonly(f, 'ma_dvcs');
		//f._findButton('Ok').click();
	}
}
function close$VoucherFilter$(sender) {try {sender.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid, k = new Array();
			if (f._extensions.length > 0) {
				var href = decodeURIComponent(window.location.href), code = '';
				if((href.match('query') || {}).length > 0) {
					var qrString = href.split("?")[1].replace('query=', ''));
					var encodedString = window.atob(qrString);
					code = decodeURIComponent(encodedString);
				} else code = f.getItemValue('ma_hd');

				if (code != '') {
					Array.add(k, {Name: 'ma_hd', Opr: '=', Value: code, Ignore: false});
					g._extensions = f._extensions;
					g.set_externalKey(k);
				}
			} else {
				var dv = $func.trim(f.getItemValue('ma_dvcs'))
				, _nh_vv1 = $func.trim(f.getItemValue('nh_vv1'))
				,_nh_vv2 = $func.trim(f.getItemValue('nh_vv2'))
				, _nh_vv3 = $func.trim(f.getItemValue('nh_vv3'))
				, _loai_sp = $func.trim(f.getItemValue('loai_sp'))
				, _kieu_sp = $func.trim(f.getItemValue('kieu_sp'))
				, _nh_hd1 = $func.trim(f.getItemValue('nh_hd1')), _nh_hd2 = $func.trim(f.getItemValue('nh_hd2'))
					, _nh_hd3 = $func.trim(f.getItemValue('nh_hd3'));

				if (_nh_vv1) Array.add(k, {Name: 'dbo.ff_ExactInlist(nh_vv1, \'' + _nh_vv1 + '\')', Opr: '=', Value: 1, Type: 'String', Ignore: false});
				if (_nh_vv2) Array.add(k, {Name: 'dbo.ff_ExactInlist(nh_vv2, \'' + _nh_vv2 + '\')', Opr: '=', Value: 1, Type: 'String', Ignore: false});
				if (_nh_vv3) Array.add(k, {Name: 'dbo.ff_ExactInlist(nh_vv3, \'' + _nh_vv3 + '\')', Opr: '=', Value: 1, Type: 'String', Ignore: false});
				if (_loai_sp) Array.add(k, {Name: 'dbo.ff_ExactInlist(loai_sp, \'' + _loai_sp + '\')', Opr: '=', Value: 1, Type: 'String', Ignore: false});
				if (_kieu_sp) Array.add(k, {Name: 'dbo.ff_ExactInlist(kieu_sp, \'' + _kieu_sp + '\')', Opr: '=', Value: 1, Type: 'String', Ignore: false});
				if (_nh_hd1) Array.add(k, {Name: 'dbo.ff_ExactInlist(nh_hd1, \'' + _nh_hd1 + '\')', Opr: '=', Value: 1, Type: 'String', Ignore: false});
				if (_nh_hd2) Array.add(k, {Name: 'dbo.ff_ExactInlist(nh_hd2, \'' + _nh_hd2 + '\')', Opr: '=', Value: 1, Type: 'String', Ignore: false});
				if (_nh_hd3) Array.add(k, {Name: 'dbo.ff_ExactInlist(nh_hd3, \'' + _nh_hd3 + '\')', Opr: '=', Value: 1, Type: 'String', Ignore: false});
				if (dv) Array.add(k, {Name: 'dbo.zcff_ExactInlist(list_dvcs, \'' + dv + '\')', Opr: '=', Value: 1, Type: 'String', Ignore: false});

				g.set_externalKey(k);
			}
			break;
		default:
				break;
	}
}
function setReferenceValue(f, a) {
	for (var i = 0; i < a.length; i++) {
		var r = $func.findField(a[i], f._fields).ItemReference;
		f.setItemValue(r, $func.findMemvar(r, f._extensions).NewValue);
	}
}
